INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '物体に力が加えられなかった場合や、加えられた力がつり合っている場合に成り立つ法則を何というか。', NULL, '["万有引力の法則","エネルギー保存の法則","慣性の法則","作用反作用の法則","オームの法則"]', 2, '["外力が働かない、またはつり合っている物体は、静止していればそのまま静止を続け、運動していれば等速直線運動を続ける。これを慣性の法則という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '圧力の単位として正しいものはどれか。', NULL, '["ジュール(J)","パスカル(Pa)","ニュートン(N)","ワット(W)","オーム(Ω)"]', 1, '["圧力は単位面積あたりに働く力の大きさを表し、単位にはパスカル(Pa)が用いられる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '音や光が物体の表面に当たり、進む方向を変えて戻ってくる現象を何というか。', NULL, '["屈折","反射","回折","干渉","吸収"]', 1, '["波が物体の表面にぶつかって跳ね返る現象を反射という。鏡に光が当たって跳ね返るのが代表例。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '2つの抵抗を直列につないだ場合の全体の抵抗について正しいものはどれか。', NULL, '["それぞれの抵抗の平均になる","それぞれの抵抗の和になる","必ず一定の値になる","抵抗が小さいほうの値になる","抵抗の逆数の和の逆数になる"]', 1, '["直列回路では、全体の抵抗は各抵抗の値の合計になる。並列回路の場合は抵抗の逆数の和の逆数になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ある物体が別の物体に力を加えると、必ず反対向きに同じ大きさの力を受け返すという法則を何というか。', NULL, '["慣性の法則","運動の第2法則","作用反作用の法則","フックの法則","万有引力の法則"]', 2, '["作用反作用の法則(ニュートンの運動の第3法則)は、ある物体が他の物体に力(作用)を及ぼすとき、その物体は同じ大きさで逆向きの力(反作用)を受けるという法則。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '高い位置にある物体がもつ、位置によって決まるエネルギーを何というか。', NULL, '["運動エネルギー","熱エネルギー","位置エネルギー","化学エネルギー","弾性エネルギー"]', 2, '["高い位置にある物体は、その高さに応じて重力による位置エネルギーをもつ。物体が落下するとこの位置エネルギーは運動エネルギーに変換される。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '光が異なる物質の境界(例えば空気中から水中)に進むとき、その進む方向が変化する現象を何というか。', NULL, '["反射","屈折","散乱","偏光","発光"]', 1, '["光が異なる媒質の境界を通過するとき、速さが変わることで進行方向が変化する現象を屈折という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '次のうち、電気を通しやすい導体として適切なものはどれか。', NULL, '["ガラス","ゴム","銅","木材","プラスチック"]', 2, '["銅などの金属は自由電子が多く存在するため電気を通しやすい導体である。ガラス、ゴム、木材、プラスチックは電気を通しにくい絶縁体である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '仕事率(単位時間あたりにする仕事の量)を表す単位はどれか。', NULL, '["ジュール(J)","ワット(W)","ニュートン(N)","パスカル(Pa)","アンペア(A)"]', 1, '["仕事率は1秒あたりにする仕事の量を表し、単位にはワット(W)が用いられる。1W=1J/秒である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '物体の「質量」と「重さ」の違いについて正しい説明はどれか。', NULL, '["質量は場所によって変化するが、重さは変化しない","質量は物体そのものが持つ量で場所によって変化しないが、重さは重力の大きさによって変化する","質量と重さはまったく同じ意味である","重さは常に質量よりも小さい","質量は力の単位で表される"]', 1, '["質量は物体そのものが持つ量で、場所が変わっても変化しない。一方、重さは物体に働く重力の大きさであり、月面上など重力が異なる場所では変化する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '物質の状態が変化するだけで、別の物質にはならない変化を何というか。', NULL, '["化学変化","物理変化","酸化","還元","中和"]', 1, '["氷が溶けて水になるなど、物質そのものは変わらず状態だけが変化することを物理変化(状態変化)という。新しい物質ができる変化は化学変化。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ある温度で、一定量の水に溶ける物質の限度量を表す言葉はどれか。', NULL, '["濃度","密度","溶解度","純度","比重"]', 2, '["溶解度は、一定量(通常100g)の水に溶ける物質の最大量を表す値であり、温度によって変化する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '水溶液の酸性・アルカリ性の強さを表す指標として使われるものはどれか。', NULL, '["pH","密度","沸点","モル濃度","比熱"]', 0, '["pHは水溶液の酸性・アルカリ性の程度を数値で表したもので、7が中性、7未満が酸性、7を超えるとアルカリ性を示す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '化学反応の速さを変化させるが、反応の前後で自身は変化しない物質を何というか。', NULL, '["反応物","生成物","触媒","溶媒","指示薬"]', 2, '["触媒は化学反応の速さを変化させる働きをもつが、反応の前後でそれ自身の量や性質は変化しない物質である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '炭素を含む物質(有機物)が完全に燃焼したときに主に生じる物質の組み合わせとして正しいものはどれか。', NULL, '["酸素と窒素","二酸化炭素と水","水素と酸素","塩化水素と水","アンモニアと二酸化炭素"]', 1, '["炭素や水素を含む有機物が完全燃焼すると、炭素は酸素と結びついて二酸化炭素に、水素は酸素と結びついて水になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '水に電解質を溶かした水溶液に電流を流すことで物質を分解する操作を何というか。', NULL, '["蒸留","中和","電気分解","ろ過","再結晶"]', 2, '["電気分解は、電解質水溶液などに電流を流すことで化合物を成分の物質に分解する操作である。水の電気分解では水素と酸素が発生する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '沸点の違いを利用して液体の混合物から純粋な物質を分離する操作を何というか。', NULL, '["蒸留","ろ過","抽出","昇華","中和"]', 0, '["蒸留は、液体の混合物を加熱し、沸点の違いを利用して気体にした後、冷やして再び液体に戻すことで成分を分離する操作である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '次のうち、金属の性質として誤っているものはどれか。', NULL, '["たたくと薄く広がる","引っ張ると細く伸びる","熱をよく伝える","電気をよく通す","すべて磁石に強く引きつけられる"]', 4, '["鉄などの一部の金属は磁石に引きつけられるが、金や銀、アルミニウムなど磁石にほとんど引きつけられない金属も多い。展性・延性・熱伝導性・電気伝導性は金属に共通する性質。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '1種類の元素だけからできている物質を何というか。', NULL, '["混合物","化合物","単体","溶液","イオン"]', 2, '["酸素(O2)や鉄(Fe)のように、1種類の元素だけからできている物質を単体という。2種類以上の元素が結びついた物質は化合物という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '石灰水に通すと白く濁る性質をもつ気体はどれか。', NULL, '["酸素","水素","二酸化炭素","窒素","アンモニア"]', 2, '["二酸化炭素を石灰水に通すと、炭酸カルシウムの白い沈殿が生じて水溶液が白く濁る。この反応は二酸化炭素の検出によく利用される。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの消化器官のうち、食べ物が口から入った後、最初に通過する順番として正しいものはどれか。', NULL, '["胃→食道→小腸","食道→胃→小腸","小腸→胃→食道","胃→小腸→食道","食道→小腸→胃"]', 1, '["食べ物は口から食道を通って胃に送られ、そこで消化された後、小腸でさらに消化・吸収される。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '細胞が酸素を使って栄養分を分解し、生きるためのエネルギーを取り出すはたらきを何というか。', NULL, '["光合成","呼吸","蒸散","発酵","分解"]', 1, '["細胞の呼吸は、酸素を用いて栄養分(グルコースなど)を分解し、生命活動に必要なエネルギーを取り出すはたらきである。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '雌雄それぞれの生殖細胞が結びついて新しい個体のもとになる細胞ができることを何というか。', NULL, '["分裂","発芽","受精","変態","発酵"]', 2, '["受精は、雌の卵細胞と雄の精細胞(精子)が結びつくことで受精卵ができる過程であり、有性生殖の重要な過程である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '生態系において、「植物→草食動物→肉食動物」のように、食べる・食べられるの関係でつながった一連のつながりを何というか。', NULL, '["生態系","食物連鎖","共生","寄生","進化"]', 1, '["食物連鎖は、生物どうしの「食べる・食べられる」という関係の連鎖を表す言葉である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの体を支え、内臓を保護するとともに、筋肉と結びついて体を動かす役割をもつ器官はどれか。', NULL, '["皮膚","骨格","血管","神経","リンパ管"]', 1, '["骨格(骨)は体を支え、脳や内臓などを保護するとともに、筋肉と協調して体を動かす役割を果たしている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '体内に侵入した細菌やウイルスなどを排除するはたらきをもつ血液の成分はどれか。', NULL, '["赤血球","白血球","血小板","血しょう","ヘモグロビン"]', 1, '["白血球は体内に侵入した細菌やウイルスなどの異物を攻撃・排除するはたらき(免疫)をもつ血液の成分である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '生物の形質を決定する遺伝情報の本体となる物質は何か。', NULL, '["タンパク質","DNA","脂質","デンプン","ATP"]', 1, '["DNA(デオキシリボ核酸)は生物の遺伝情報を担う本体となる物質であり、二重らせん構造をとっている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '植物が光合成によって光エネルギーを使い、二酸化炭素と水からつくり出す主な栄養分はどれか。', NULL, '["タンパク質","デンプン(糖)","脂肪","ビタミン","ミネラル"]', 1, '["光合成では、光エネルギーを利用して二酸化炭素と水からデンプン(糖)などの有機物と酸素がつくられる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトが光の刺激を受け取る感覚器官はどれか。', NULL, '["耳","鼻","目","舌","皮膚"]', 2, '["目は光の刺激を受け取る感覚器官であり、網膜で受け取った光の情報が視神経を通って脳に伝えられる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '納豆やヨーグルトなど、微生物のはたらきによって食品の風味や保存性が変化する現象を何というか。', NULL, '["腐敗","発酵","蒸散","同化","分解のみ"]', 1, '["発酵は、酵母や乳酸菌などの微生物のはたらきによって食品が人にとって有用な形に変化する現象であり、納豆やヨーグルト、みそなどの製造に利用されている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '寒気が暖気の下にもぐりこむように進む前線を何というか。', NULL, '["温暖前線","寒冷前線","停滞前線","閉塞前線","偏西前線"]', 1, '["寒冷前線は寒気が暖気の下にもぐりこむように進む前線で、通過時には積乱雲が発達し、短時間に強い雨や雷を伴うことが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '地震が発生したときに最初に到達する、伝わる速さの速い波を何というか。', NULL, '["S波","P波","表面波","音波","電磁波"]', 1, '["P波(初期微動を起こす波)はS波よりも伝わる速さが速く、地震発生時に最初に観測される波である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '自ら光や熱を出して輝いている天体を何というか。', NULL, '["惑星","衛星","恒星","彗星","小惑星"]', 2, '["恒星は太陽のように自ら核融合反応によって光や熱を出して輝く天体である。惑星や衛星は自ら光を発せず、恒星の光を反射して見えている。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'マグマが地下深くでゆっくり冷え固まってできる、大きな結晶が組み合わさった岩石を何というか。', NULL, '["火山岩","深成岩","堆積岩","変成岩","凝灰岩"]', 1, '["深成岩は、マグマが地下深くで長い時間をかけてゆっくり冷え固まってできる火成岩で、大きな結晶がそろった等粒状組織をもつ。花こう岩などが代表例。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '地球を取り巻く大気の層のうち、地表に最も近く、雲の発生や天気の変化が起こる層はどれか。', NULL, '["成層圏","対流圏","中間圏","熱圏","外気圏"]', 1, '["対流圏は地表から最も近い大気の層であり、雲の発生や降水など、私たちが経験する天気の変化のほとんどはこの層で起こる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '海面が周期的に満ちたり引いたりする潮の満ち引きの主な原因はどれか。', NULL, '["地球の自転速度の変化","月と太陽の引力の影響","海水温の変化","大気圧の変化のみ","地震の発生"]', 1, '["潮の満ち引き(潮汐)は、主に月の引力、そして太陽の引力の影響によって海水が引き寄せられることで生じる周期的な現象である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '太陽系が属する、数千億個ともいわれる恒星の集まりを何というか。', NULL, '["太陽系","銀河系","星団","星雲","超銀河団"]', 1, '["銀河系(天の川銀河)は太陽系が属する恒星の大集団で、数千億個の恒星から構成されているといわれる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '地層が堆積した当時の年代を知る手がかりとなる、限られた時代にだけ広く生息していた生物の化石を何というか。', NULL, '["示相化石","示準化石","生痕化石","標準化石(示準化石と同義)","化石燃料"]', 1, '["示準化石は、限られた時代にのみ広い範囲で生息していた生物の化石で、地層が堆積した年代を推定する手がかりとなる。アンモナイトや三葉虫などが代表例。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '周囲より気圧が高く、中心付近で下降気流が生じて晴れやすい気圧配置を何というか。', NULL, '["低気圧","高気圧","台風","前線","熱帯低気圧"]', 1, '["高気圧は周囲よりも気圧が高い場所で、中心付近では下降気流が生じるため雲ができにくく、晴天になりやすい。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '長期間にわたり、気温の変化や風雨の影響を受けて岩石が表面からくずれていく現象を何というか。', NULL, '["侵食","堆積","風化","運搬","隆起"]', 2, '["風化は、気温の変化や水・風などの影響によって、岩石がその場で徐々にもろくくずれていく現象である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
